 ck('Cinq objectifs locaux conservés',initial['step']==0 and initial['flags']=={'relay':False,'newt':False,'defense':False})
 d=state('01-avant-sas-optique');load(pg,d);ck('Import avant nouveau raccord exact',export(pg)==d)
